import type { HTMLAttributes } from "react";
import { cn } from "@/lib/utils";

type BadgeVariant = "default" | "primary" | "success" | "warning" | "danger" | "rewards";

const variants: Record<BadgeVariant, string> = {
  default: "bg-muted text-muted-foreground",
  primary: "bg-primary/10 text-primary",
  success: "bg-success/10 text-success",
  warning: "bg-warning/10 text-warning",
  danger: "bg-danger/10 text-danger",
  rewards: "bg-rewards/10 text-rewards",
};

export function Badge({
  className,
  variant = "default",
  ...props
}: HTMLAttributes<HTMLSpanElement> & { variant?: BadgeVariant }) {
  return (
    <span
      className={cn(
        "inline-flex items-center gap-1 rounded-full px-2.5 py-1 text-xs font-bold",
        variants[variant],
        className,
      )}
      {...props}
    />
  );
}

import type { ButtonHTMLAttributes } from "react";
import { cn } from "@/lib/utils";

type ButtonVariant = "primary" | "secondary" | "ghost" | "dark";

const variants: Record<ButtonVariant, string> = {
  primary: "bg-primary text-white shadow-lift hover:-translate-y-0.5 hover:bg-primary-600",
  secondary: "bg-card text-text ring-1 ring-border hover:-translate-y-0.5 hover:shadow-soft",
  ghost: "bg-transparent text-text hover:bg-muted",
  dark: "bg-dark text-white shadow-soft hover:-translate-y-0.5",
};

export function Button({
  className,
  variant = "primary",
  ...props
}: ButtonHTMLAttributes<HTMLButtonElement> & { variant?: ButtonVariant }) {
  return (
    <button
      className={cn(
        "inline-flex min-h-12 items-center justify-center gap-2 rounded-2xl px-5 text-sm font-extrabold transition-transform duration-200 will-change-transform focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-primary disabled:pointer-events-none disabled:opacity-50",
        variants[variant],
        className,
      )}
      {...props}
    />
  );
}

import { useEffect, type ReactNode } from "react";
import { AnimatePresence, motion } from "framer-motion";
import { X } from "lucide-react";
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion";

type DialogProps = {
  open: boolean;
  onClose: () => void;
  children: ReactNode;
  title?: string;
  maxWidth?: string;
};

export function Dialog({ open, onClose, children, title, maxWidth = "max-w-md" }: DialogProps) {
  const reduced = usePrefersReducedMotion();

  useEffect(() => {
    function onKey(e: KeyboardEvent) {
      if (e.key === "Escape") onClose();
    }
    if (open) {
      document.addEventListener("keydown", onKey);
      document.body.style.overflow = "hidden";
    }
    return () => {
      document.removeEventListener("keydown", onKey);
      document.body.style.overflow = "";
    };
  }, [open, onClose]);

  return (
    <AnimatePresence>
      {open && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
          <motion.div
            initial={reduced ? { opacity: 0 } : { opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="absolute inset-0 bg-dark/50 backdrop-blur-sm"
            onClick={onClose}
          />
          <motion.div
            initial={reduced ? { opacity: 0 } : { opacity: 0, scale: 0.95, y: 10 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={reduced ? { opacity: 0 } : { opacity: 0, scale: 0.95, y: 10 }}
            transition={{ type: "spring", stiffness: 350, damping: 30 }}
            className={`relative z-10 w-full ${maxWidth} rounded-3xl border border-border bg-card p-6 shadow-lift`}
            role="dialog"
            aria-modal="true"
            aria-label={title}
          >
            {title && (
              <div className="mb-4 flex items-center justify-between">
                <h2 className="font-heading text-lg font-black">{title}</h2>
                <button
                  onClick={onClose}
                  aria-label="Close dialog"
                  className="grid size-9 place-items-center rounded-xl bg-muted text-muted-foreground transition-colors hover:text-text"
                >
                  <X size={18} />
                </button>
              </div>
            )}
            {children}
          </motion.div>
        </div>
      )}
    </AnimatePresence>
  );
}

export function IconButton({ children, ...props }: React.ButtonHTMLAttributes<HTMLButtonElement>) {
  return (
    <button {...props} className={`inline-grid place-items-center rounded-xl p-2 ${props.className ?? ""}`}>
      {children}
    </button>
  );
}

import { Card } from "@/components/ui/card";

export function Feedback({ message }: { message: string }) {
  return (
    <Card className="rounded-xl bg-primary/10"> 
      <p className="font-bold text-primary">{message}</p>
    </Card>
  );
}

import type { HTMLAttributes } from "react";
import { cn } from "@/lib/utils";

export function Skeleton({ className, ...props }: HTMLAttributes<HTMLDivElement>) {
  const prefersReduced = typeof window !== "undefined" && window.matchMedia?.("(prefers-reduced-motion: reduce)")?.matches;
  return <div className={cn(!prefersReduced ? "animate-pulse rounded-2xl bg-muted" : "rounded-2xl bg-muted", className)} {...props} />;
}

import type { ReactNode } from "react";
import { cn } from "@/lib/utils";

type EmptyStateProps = {
  icon?: ReactNode;
  title: string;
  description?: string;
  action?: ReactNode;
  className?: string;
};

export function EmptyState({ icon, title, description, action, className }: EmptyStateProps) {
  return (
    <div className={cn("flex flex-col items-center justify-center px-6 py-16 text-center", className)}>
      {icon && (
        <div className="mb-5 grid size-20 place-items-center rounded-3xl bg-primary/10 text-primary">
          {icon}
        </div>
      )}
      <h3 className="font-heading text-xl font-black">{title}</h3>
      {description && (
        <p className="mt-2 max-w-sm text-sm text-muted-foreground">{description}</p>
      )}
      {action && <div className="mt-6">{action}</div>}
    </div>
  );
}

import { Card } from "@/components/ui/card";
import { AnimatePresence, motion } from "framer-motion";
import { X } from "lucide-react";
import { useEffect } from "react";
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion";

export function BottomSheet({ open, onClose, children }: { open?: boolean; onClose?: () => void; children: React.ReactNode }) {
  const reduced = usePrefersReducedMotion();

  useEffect(() => {
    function onKey(e: KeyboardEvent) {
      if (e.key === "Escape" && onClose) onClose();
    }
    if (open) document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [open, onClose]);

  return (
    <AnimatePresence>
      {open && (
        <div className="fixed inset-0 z-50 grid place-items-end bg-dark/40 backdrop-blur-sm">
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="absolute inset-0"
            onClick={onClose}
          />
          <motion.div
            initial={reduced ? { opacity: 0 } : { y: "100%" }}
            animate={{ y: 0, opacity: 1 }}
            exit={reduced ? { opacity: 0 } : { y: "100%" }}
            transition={{ type: "spring", stiffness: 300, damping: 30 }}
            className="relative z-10 w-full max-w-3xl"
          >
            <Card className="rounded-t-3xl p-6">
              <div className="mb-4 flex items-center justify-between">
                <div className="mx-auto h-1.5 w-12 rounded-full bg-muted" />
                <button
                  onClick={onClose}
                  aria-label="Close"
                  className="grid size-9 place-items-center rounded-xl bg-muted text-muted-foreground"
                >
                  <X size={18} />
                </button>
              </div>
              {children}
            </Card>
          </motion.div>
        </div>
      )}
    </AnimatePresence>
  );
}

import { Search } from "lucide-react";
import { Input } from "./input";

type SearchInputProps = {
  value?: string;
  onChange?: (value: string) => void;
  placeholder?: string;
  onSearch?: (value: string) => void;
};

export function SearchInput({
  value = "",
  onChange,
  placeholder = "Search restaurants, meals…",
  onSearch,
}: SearchInputProps) {
  return (
    <Input
      icon={<Search size={18} />}
      placeholder={placeholder}
      value={value}
      onChange={(e) => onChange?.(e.target.value)}
      onKeyDown={(e) => {
        if (e.key === "Enter") onSearch?.(value);
      }}
      aria-label="Search"
    />
  );
}

import { cn } from "@/lib/utils";

export function Checkbox({ checked, onChange, label }: { checked?: boolean; onChange?: (v: boolean) => void; label?: string }) {
  return (
    <label className="inline-flex cursor-pointer items-center gap-2.5">
      <input
        type="checkbox"
        checked={checked}
        onChange={(e) => onChange?.(e.target.checked)}
        className="size-5 rounded-md border-border accent-primary"
      />
      {label ? <span className="text-sm font-medium">{label}</span> : null}
    </label>
  );
}

export function Radio({ checked, onChange, name, value, label }: { checked?: boolean; onChange?: () => void; name?: string; value?: string; label?: string }) {
  return (
    <label className="inline-flex cursor-pointer items-center gap-2.5">
      <input
        type="radio"
        name={name}
        value={value}
        checked={checked}
        onChange={onChange}
        className={cn("size-5 border-border accent-primary")}
      />
      {label ? <span className="text-sm font-medium">{label}</span> : null}
    </label>
  );
}
